// Normalize input from Form Trigger, Webhook REST API, or Manual Canvas Execution
const items = $input.all();
const rawItem = items[0]?.json || {};
const body = rawItem.body || {};
const query = rawItem.query || {};
const incomingBinary = items[0]?.binary || {};

let triggerSource = 'manual';
if (rawItem.headers || rawItem.query || (body && Object.keys(body).length > 0 && !rawItem['Post Text'] && !rawItem['field-0'])) {
  triggerSource = 'webhook';
} else if (rawItem.submittedAt || rawItem['Post Text'] || rawItem['field-0']) {
  triggerSource = 'form';
}

// 1. Resolve Execution Mode (dry_run vs live)
const rawMode = (
  rawItem['Execution Mode'] ||
  rawItem.mode ||
  rawItem['field-4'] ||
  body.mode ||
  body['Execution Mode'] ||
  query.mode ||
  ''
).toString().toLowerCase();

let dryRun = false;
if (
  rawItem.dry_run === true ||
  rawItem.dry_run === 'true' ||
  body.dry_run === true ||
  body.dry_run === 'true' ||
  query.dry_run === 'true' ||
  rawMode.includes('dry') ||
  rawMode.includes('simulation') ||
  rawMode.includes('preview')
) {
  dryRun = true;
}

// 2. Resolve Post Text
const postText = (
  rawItem['Post Text'] ||
  rawItem.post_text ||
  rawItem.text ||
  rawItem.content ||
  rawItem['field-0'] ||
  body['Post Text'] ||
  body.post_text ||
  body.text ||
  body.content ||
  query.text ||
  'Automated update from AI Social Media Publisher.'
).toString().trim();

// 3. Resolve Target Platforms (both, x, linkedin)
const rawPlatforms = (
  rawItem['Target Platforms'] ||
  rawItem.target_platforms ||
  rawItem.platforms ||
  rawItem.platform ||
  rawItem['field-1'] ||
  body['Target Platforms'] ||
  body.platforms ||
  body.platform ||
  query.platform ||
  'both'
).toString().toLowerCase();

let postToX = false;
let postToLinkedIn = false;

if (rawPlatforms.includes('both') || rawPlatforms === 'all') {
  postToX = true;
  postToLinkedIn = true;
} else if (rawPlatforms.includes('x') || rawPlatforms.includes('twitter')) {
  postToX = true;
} else if (rawPlatforms.includes('linkedin')) {
  postToLinkedIn = true;
} else {
  postToX = true;
  postToLinkedIn = true;
}

// 4. Resolve Media Type & Links
const rawMediaType = (
  rawItem['Media Type'] ||
  rawItem.media_type ||
  rawItem['field-2'] ||
  body['Media Type'] ||
  body.media_type ||
  'Text Only'
).toString().toUpperCase();

let mediaType = 'NONE';
if (rawMediaType.includes('IMAGE') || rawMediaType.includes('PHOTO')) {
  mediaType = 'IMAGE';
} else if (rawMediaType.includes('VIDEO')) {
  mediaType = 'VIDEO';
} else if (rawMediaType.includes('ARTICLE') || rawMediaType.includes('LINK')) {
  mediaType = 'ARTICLE';
}

// 5. Universal Direct File Upload Check (Form Trigger, Webhook Multipart, or Memory Binary)
let hasBinaryMedia = false;
let standardizedBinary = {};

const binaryKeys = Object.keys(incomingBinary);
let binObj = null;

if (incomingBinary.data && (incomingBinary.data.data || incomingBinary.data.id || incomingBinary.data.mimeType || incomingBinary.data.fileName)) {
  binObj = incomingBinary.data;
} else {
  for (const k of binaryKeys) {
    const candidate = incomingBinary[k];
    if (candidate && (candidate.data || candidate.id || candidate.mimeType || candidate.fileName)) {
      binObj = candidate;
      break;
    }
  }
}

if (binObj) {
  hasBinaryMedia = true;
  standardizedBinary['data'] = binObj;

  const mime = (binObj.mimeType || '').toLowerCase();
  const fileName = (binObj.fileName || '').toLowerCase();

  if (mime.includes('video') || fileName.endsWith('.mp4') || fileName.endsWith('.mov') || fileName.endsWith('.webm') || fileName.endsWith('.mkv') || fileName.endsWith('.avi')) {
    mediaType = 'VIDEO';
  } else if (mime.includes('image') || fileName.endsWith('.jpg') || fileName.endsWith('.jpeg') || fileName.endsWith('.png') || fileName.endsWith('.webp') || fileName.endsWith('.gif')) {
    if (mediaType !== 'VIDEO') {
      mediaType = 'IMAGE';
    }
  } else if (mediaType === 'NONE') {
    mediaType = 'IMAGE';
  }
}

// 6. Check for Base64 File Upload in JSON
const rawBase64 = (
  rawItem.media_base64 ||
  rawItem.file_base64 ||
  rawItem.video_base64 ||
  rawItem.image_base64 ||
  rawItem.video ||
  rawItem.media ||
  body.media_base64 ||
  body.file_base64 ||
  body.video_base64 ||
  body.image_base64 ||
  body.video ||
  body.media ||
  ''
).toString().trim();

if (!hasBinaryMedia && rawBase64 && (rawBase64.length > 50 || rawBase64.includes(';base64,'))) {
  let cleanBase64 = rawBase64;
  const fileName = (rawItem.fileName || rawItem.file_name || body.fileName || body.file_name || 'uploaded_media').toString();
  let detectedMime = (rawItem.media_mime_type || body.media_mime_type || '').toString();

  if (!detectedMime && cleanBase64.includes(';base64,')) {
    const parts = cleanBase64.split(';base64,');
    detectedMime = parts[0].replace('data:', '') || '';
    cleanBase64 = parts[1];
  }

  if (!detectedMime && fileName) {
    const ext = fileName.split('.').pop().toLowerCase();
    if (['mp4', 'mov', 'webm', 'mkv', 'avi'].includes(ext)) {
      detectedMime = ext === 'mov' ? 'video/quicktime' : 'video/' + ext;
    } else if (['jpg', 'jpeg'].includes(ext)) {
      detectedMime = 'image/jpeg';
    } else if (ext === 'png') {
      detectedMime = 'image/png';
    } else if (ext === 'webp') {
      detectedMime = 'image/webp';
    }
  }

  if (!detectedMime) {
    detectedMime = (mediaType === 'VIDEO') ? 'video/mp4' : 'image/jpeg';
  }

  standardizedBinary['data'] = {
    data: cleanBase64,
    mimeType: detectedMime,
    fileName: fileName.includes('.') ? fileName : (fileName + (detectedMime.includes('video') ? '.mp4' : '.jpg'))
  };
  hasBinaryMedia = true;

  if (detectedMime.includes('video') || mediaType === 'VIDEO') {
    mediaType = 'VIDEO';
  } else if (mediaType === 'NONE') {
    mediaType = detectedMime.includes('video') ? 'VIDEO' : 'IMAGE';
  }
}

// 7. Resolve Media URL (Only used if no file was uploaded directly)
let mediaUrl = (
  rawItem['Media URL (Image or Video Direct Link)'] ||
  rawItem.media_url ||
  rawItem.image_url ||
  rawItem.video_url ||
  rawItem['field-5'] ||
  body['Media URL'] ||
  body.media_url ||
  body.image_url ||
  body.video_url ||
  query.media_url ||
  ''
).toString().trim();

if (mediaUrl.includes('localhost:3000')) {
  mediaUrl = mediaUrl.replace('localhost:3000', 'host.docker.internal:3000');
} else if (mediaUrl.includes('127.0.0.1:3000')) {
  mediaUrl = mediaUrl.replace('127.0.0.1:3000', 'host.docker.internal:3000');
}

// Needs download ONLY if URL is given AND no file was already uploaded directly
const needsMediaDownload = (mediaType === 'IMAGE' || mediaType === 'VIDEO') && Boolean(mediaUrl) && !hasBinaryMedia;

const articleUrl = (
  rawItem['Article / Link URL'] ||
  rawItem.article_url ||
  rawItem.url ||
  rawItem['field-6'] ||
  body['Article / Link URL'] ||
  body.article_url ||
  body.url ||
  query.url ||
  ''
).toString().trim();

// 8. Resolve Tags / Hashtags
const rawTags = (
  rawItem['Hashtags / Tags'] ||
  rawItem.hashtags ||
  rawItem.tags ||
  rawItem['field-7'] ||
  body['Hashtags / Tags'] ||
  body.hashtags ||
  body.tags ||
  query.tags ||
  ''
).toString().trim();

let cleanTags = [];
if (rawTags) {
  cleanTags = rawTags
    .split(/[,\s]+/)
    .map(t => t.trim())
    .filter(Boolean)
    .map(t => (t.startsWith('#') ? t : '#' + t));
}
const tagsString = cleanTags.join(' ');

// 9. Format Platform-Specific Copy
let xText = postText;
if (tagsString) {
  xText = postText + '\n\n' + tagsString;
}

const xCharCount = xText.length;
const isLongTweet = xCharCount > 280;

let linkedinText = postText;
if (tagsString) {
  linkedinText = postText + '\n\n' + tagsString;
}

// 10. LinkedIn Settings
const rawVisibility = (
  rawItem['LinkedIn Visibility'] ||
  rawItem.linkedin_visibility ||
  rawItem.visibility ||
  rawItem['field-8'] ||
  body['LinkedIn Visibility'] ||
  body.linkedin_visibility ||
  body.visibility ||
  'PUBLIC'
).toString().toUpperCase();

const linkedinVisibility = rawVisibility.includes('CONN') ? 'CONNECTIONS' : 'PUBLIC';

const rawPostAs = (
  rawItem['LinkedIn Post As'] ||
  rawItem.linkedin_post_as ||
  rawItem.post_as ||
  rawItem['field-9'] ||
  body['LinkedIn Post As'] ||
  body.linkedin_post_as ||
  'person'
).toString().toLowerCase();

const linkedinPostAs = rawPostAs.includes('org') ? 'organization' : 'person';

const linkedinOrgUrn = (
  rawItem['LinkedIn Organization URN'] ||
  rawItem.linkedin_organization_urn ||
  rawItem.organization_urn ||
  rawItem['field-10'] ||
  body.organization_urn ||
  ''
).toString().trim();

// 11. X Reply Settings
const rawReplySettings = (
  rawItem['X / Twitter Reply Settings'] ||
  rawItem.x_reply_settings ||
  rawItem.reply_settings ||
  rawItem['field-11'] ||
  body.x_reply_settings ||
  'everyone'
).toString();

const xReplySettings = ['following', 'mentionedUsers'].includes(rawReplySettings)
  ? rawReplySettings
  : 'everyone';

const outputItem = {
  json: {
    trigger_source: triggerSource,
    dry_run: dryRun,
    post_text: postText,
    platforms_requested: rawPlatforms,
    post_to_x: postToX,
    post_to_linkedin: postToLinkedIn,
    media_type: mediaType,
    media_url: mediaUrl,
    article_url: articleUrl,
    hashtags: cleanTags,
    tags_string: tagsString,
    x_text: xText,
    x_char_count: xCharCount,
    is_long_tweet: isLongTweet,
    x_reply_settings: xReplySettings,
    linkedin_text: linkedinText,
    linkedin_visibility: linkedinVisibility,
    linkedin_post_as: linkedinPostAs,
    linkedin_organization_urn: linkedinOrgUrn,
    needs_media_download: needsMediaDownload,
    has_binary_media: hasBinaryMedia,
    created_at: new Date().toISOString()
  }
};

if (hasBinaryMedia) {
  outputItem.binary = standardizedBinary;
}

return [outputItem];

// Ensure binary property is consistently accessible as 'data'
const items = $input.all();
const item = items[0] || { json: {} };
const normItem = $('Normalize & Validate Post Input').first();
const baseJson = { ...(normItem?.json || {}), ...item.json };

// Find binary either on input (from Download Media Binary or bypass) or from normItem (from direct upload / base64)
const binary = item.binary || normItem?.binary || {};

let normalizedBinary = {};
const keys = Object.keys(binary);
if (keys.length > 0) {
  const primaryKey = keys.includes('data') ? 'data' : keys[0];
  if (binary[primaryKey]) {
    normalizedBinary['data'] = binary[primaryKey];
  }
}

const hasBinary = Object.keys(normalizedBinary).length > 0;

return [{
  json: {
    ...baseJson,
    has_binary_data: hasBinary,
    media_status: hasBinary ? "ready" : (baseJson.media_type === "NONE" ? "text_only" : "not_found")
  },
  ...(hasBinary ? { binary: normalizedBinary } : {})
}];

// Simulate X Response
const item = $input.first();
const fakeTweetId = '183' + Math.floor(100000000000000 + Math.random() * 900000000000000);
return [{
  json: {
    ...item.json,
    x_result: {
      attempted: true,
      simulated: true,
      success: true,
      tweet_id: fakeTweetId,
      tweet_url: 'https://twitter.com/i/web/status/' + fakeTweetId,
      text: item.json.x_text
    }
  },
  ...(item.binary ? { binary: item.binary } : {})
}];

// Capture live X result and attach to item
const item = $input.first()?.json || {};
const origItem = $('Standardize Media Binary').first();
const origJson = origItem?.json || {};
const origBinary = origItem?.binary || {};

let xResult = { attempted: true, success: false };
const tweetId = item.id || item.data?.id;

if (tweetId) {
  xResult.success = true;
  xResult.tweet_id = tweetId;
  xResult.tweet_url = 'https://twitter.com/i/web/status/' + tweetId;
  xResult.text = item.text || item.data?.text || origJson.x_text;
} else if (item.error || item.errors) {
  xResult.error = item.error || item.errors;
} else {
  xResult.raw = item;
}

return [{
  json: {
    ...origJson,
    x_result: xResult
  },
  ...(Object.keys(origBinary).length > 0 ? { binary: origBinary } : {})
}];

// X was skipped
const item = $input.first();
return [{
  json: {
    ...item.json,
    x_result: { attempted: false, skipped: true }
  },
  ...(item.binary ? { binary: item.binary } : {})
}];

// Simulate LinkedIn Response
const item = $input.first();
const fakeLinkedinUrn = 'urn:li:share:7' + Math.floor(100000000000000000 + Math.random() * 900000000000000000);
return [{
  json: {
    ...item.json,
    linkedin_result: {
      attempted: true,
      simulated: true,
      success: true,
      post_urn: fakeLinkedinUrn,
      post_url: 'https://www.linkedin.com/feed/update/' + fakeLinkedinUrn,
      text: item.json.linkedin_text,
      visibility: item.json.linkedin_visibility
    }
  },
  ...(item.binary ? { binary: item.binary } : {})
}];

// Route LinkedIn posting by media category with strict binary validation
const item = $input.first();
const origJson = item?.json || {};
const mediaType = (origJson.media_type || 'NONE').toUpperCase();

const normItem = $('Normalize & Validate Post Input').first();
const stdItem = $('Standardize Media Binary').first();
const bin = item?.binary?.data || stdItem?.binary?.data || normItem?.binary?.data;

const hasBinary = Boolean(bin && (bin.data || bin.id || bin.mimeType || bin.fileName)) || origJson.has_binary_data === true;

let fileSizeBytes = 0;
if (bin) {
  if (bin.fileSize) {
    if (typeof bin.fileSize === 'number') {
      fileSizeBytes = bin.fileSize;
    } else if (typeof bin.fileSize === 'string') {
      const match = bin.fileSize.match(/^([\d.]+)\s*([A-Za-z]+)?$/);
      if (match) {
        const num = parseFloat(match[1]);
        const unit = (match[2] || 'B').toUpperCase();
        if (unit.startsWith('M')) fileSizeBytes = Math.round(num * 1024 * 1024);
        else if (unit.startsWith('K')) fileSizeBytes = Math.round(num * 1024);
        else if (unit.startsWith('G')) fileSizeBytes = Math.round(num * 1024 * 1024 * 1024);
        else fileSizeBytes = Math.round(num);
      }
    }
  }
  if (!fileSizeBytes && bin.data) {
    try {
      fileSizeBytes = Buffer.byteLength(bin.data, 'base64');
    } catch (e) {
      fileSizeBytes = Math.round(bin.data.length * 3 / 4);
    }
  }
}
if (!fileSizeBytes) {
  fileSizeBytes = 5000000;
}

const authorUrn = (origJson.linkedin_post_as === 'organization' && origJson.linkedin_organization_urn)
  ? (origJson.linkedin_organization_urn.startsWith('urn:li:') ? origJson.linkedin_organization_urn : 'urn:li:organization:' + origJson.linkedin_organization_urn)
  : ((origJson.linkedin_person_urn || '').startsWith('urn:li:') ? origJson.linkedin_person_urn : 'urn:li:person:' + (origJson.linkedin_person_urn || ''));

let route = 'text';
if (mediaType === 'IMAGE') {
  route = hasBinary ? 'image' : 'text';
} else if (mediaType === 'VIDEO') {
  route = hasBinary ? 'video' : 'text';
} else if (mediaType === 'ARTICLE' && origJson.article_url) {
  route = 'article';
}

return [{
  json: {
    ...origJson,
    author_urn: authorUrn,
    file_size_bytes: fileSizeBytes,
    linkedin_route: route,
    media_fallback_to_text: (mediaType === 'IMAGE' || mediaType === 'VIDEO') && !hasBinary
  },
  ...(bin ? { binary: { data: bin } } : (item?.binary ? { binary: item.binary } : {}))
}];

