// Capture live LinkedIn result and attach to item (supports image, article, text, and video)
const item = $input.first()?.json || {};
const origItem = $('Route LinkedIn Content Type').first();
const origJson = origItem?.json || {};

let linkedinResult = { attempted: true, success: false };

const rawUrn = (
  item.id ||
  item.urn ||
  item.headers?.['x-restli-id'] ||
  item['x-restli-id'] ||
  item.value?.asset ||
  (item.headers?.location ? decodeURIComponent(item.headers.location.replace('/posts/', '')) : '') ||
  ''
);

if (item.error || item.body?.error) {
  linkedinResult.error = item.error || item.body?.error;
} else if (rawUrn || item.statusCode === 201 || item.statusCode === 200) {
  linkedinResult.success = true;
  linkedinResult.post_urn = rawUrn;
  linkedinResult.post_url = rawUrn ? ('https://www.linkedin.com/feed/update/' + rawUrn) : 'https://www.linkedin.com/feed/';
  linkedinResult.visibility = origJson.linkedin_visibility || 'PUBLIC';
} else {
  linkedinResult.raw = item;
}

return [{
  json: {
    ...origJson,
    linkedin_result: linkedinResult
  }
}];

// LinkedIn was skipped
const item = $input.first();
return [{
  json: {
    ...item.json,
    linkedin_result: { attempted: false, skipped: true }
  }
}];

// Final summary - NO external $() node references needed!
const item = $input.first()?.json || {};

const xResult = item.x_result || { attempted: false };
const linkedinResult = item.linkedin_result || { attempted: false };

let overallStatus = 'success';
if (xResult.attempted && !xResult.success && linkedinResult.attempted && !linkedinResult.success) {
  overallStatus = 'failed';
} else if ((xResult.attempted && !xResult.success) || (linkedinResult.attempted && !linkedinResult.success)) {
  overallStatus = 'partial_success';
}

return [{
  json: {
    status: overallStatus,
    mode: item.dry_run ? "DRY_RUN" : "LIVE",
    timestamp: new Date().toISOString(),
    platforms: {
      x: xResult,
      linkedin: linkedinResult
    },
    post_summary: {
      text: item.post_text,
      hashtags: item.hashtags || [],
      media_type: item.media_type,
      media_url: item.media_url || null,
      article_url: item.article_url || null
    }
  }
}];

// Automatically extract person URN / sub from LinkedIn userinfo
const userItem = $input.first()?.json || {};
const prevItem = $('Is LinkedIn Dry Run?').first();
const normBinaryItem = $('Standardize Media Binary').first();

const prevJson = prevItem?.json || {};
const binary = (prevItem?.binary && prevItem.binary.data) ? prevItem.binary : (normBinaryItem?.binary || {});

// sub is standard OpenID Connect, id is legacy
const personId = userItem.sub || userItem.id || prevJson.linkedin_person_urn || '';

return [{
  json: {
    ...prevJson,
    linkedin_person_urn: personId
  },
  ...(Object.keys(binary).length > 0 ? { binary: binary } : {})
}];

// Extract official video URN and upload URL instructions (supporting multi-part uploads)
const item = $input.first()?.json || {};
const prevItem = $('Route LinkedIn Content Type').first();
const stdItem = $('Standardize Media Binary').first();
const prevJson = prevItem?.json || {};
const bin = prevItem?.binary?.data || stdItem?.binary?.data;

const uploadInstructions = item.value?.uploadInstructions || [];
const videoUrn = item.value?.video || item.value?.asset || '';

if (!uploadInstructions || uploadInstructions.length === 0) {
  return [{
    json: {
      ...prevJson,
      video_upload_url: '',
      video_urn: videoUrn,
      video_register_raw: item
    },
    ...(bin ? { binary: { data: bin } } : {})
  }];
}

let fullBuffer = null;
if (bin?.data) {
  fullBuffer = Buffer.from(bin.data, 'base64');
}

const outputItems = [];

for (let i = 0; i < uploadInstructions.length; i++) {
  const instruction = uploadInstructions[i];
  const firstByte = instruction.firstByte || 0;
  const lastByte = instruction.lastByte || (fullBuffer ? fullBuffer.length - 1 : 0);

  let chunkBinary = bin;
  if (fullBuffer) {
    const chunkBuffer = fullBuffer.subarray(firstByte, lastByte + 1);
    chunkBinary = {
      data: chunkBuffer.toString('base64'),
      mimeType: 'application/octet-stream',
      fileName: 'chunk_' + i + '.bin'
    };
  }

  outputItems.push({
    json: {
      ...prevJson,
      video_upload_url: instruction.uploadUrl,
      video_urn: videoUrn,
      video_register_raw: item,
      chunk_index: i,
      total_chunks: uploadInstructions.length,
      first_byte: firstByte,
      last_byte: lastByte
    },
    binary: {
      data: chunkBinary
    }
  });
}

return outputItems;

