// Combine upload status and extract ETags from each uploaded part
const uploadResults = $input.all();
const origItem = $('Prepare Video Upload').first();
const origJson = origItem?.json || {};

const uploadedPartIds = [];
for (const r of uploadResults) {
  const headers = r.json?.headers || {};
  const etag = headers.etag || headers.ETag || '';
  if (etag) {
    uploadedPartIds.push(etag.replace(/^"|"$/g, ''));
  }
}

const allSucceeded = uploadResults.every(r => !r.json?.error && (r.json?.statusCode < 400 || !r.json?.statusCode));

return [{
  json: {
    ...origJson,
    video_upload_chunks_count: uploadResults.length,
    video_upload_success: allSucceeded,
    uploaded_part_ids: uploadedPartIds,
    upload_token: origJson.video_register_raw?.value?.uploadToken || ''
  }
}];

// Attach finalize result while preserving full post metadata
const finalizeResult = $input.first()?.json || {};
const origItem = $('Prepare Video Post Data').first();
const origJson = origItem?.json || {};

return [{
  json: {
    ...origJson,
    video_finalize_result: finalizeResult
  }
}];
